// SwarmMeshNetwork.h#pragma once#include <vector>#include <map>class NPC;class SystemManager;class SwarmMeshNetwork {private:    uint32_t m_gridID;    float m_trueSec;    float m_dangerSec; // Derived from your system manager context [0.1 - 2.0]        std::vector<NPC*> m_meshNodes;    SwarmMeshTelemetry m_activeTelemetry;public:    SwarmMeshNetwork(uint32_t gridID, float trueSec, float dangerSec)         : m_gridID(gridID), m_trueSec(trueSec), m_dangerSec(dangerSec) {}    void RegisterDroneNode(NPC* pDrone);    void UnregisterDroneNode(NPC* pDrone);        // Recalculates swarm attributes based on current entity numbers and DangerSec    void RecalculateMeshTopology();        // Getters for individual drone AI scripts to query    const SwarmMeshTelemetry& GetMeshTelemetry() const { return m_activeTelemetry; }    size_t GetNodeCount() const { return m_meshNodes.size(); }};